const row = $input.first()?.json || {};
if (row.ok === false || row.ok === 'f') {
  return [{ json: { ok: false, error: row.error || 'Image generation was not submitted.' } }];
}
function parse(value, fallback) {
  if (value == null) return fallback;
  if (typeof value === 'string') {
    try { return JSON.parse(value); } catch { return fallback; }
  }
  return value;
}
const job = parse(row.job, null);
const generation = parse(row.generation, null);
if (!job || !generation) {
  return [{ json: { ok: false, error: 'Generation submission did not return job metadata.' } }];
}

const promptPack = generation.promptPack || job.promptPack || {};
const referenceImages = Array.isArray(promptPack.referenceImages) ? promptPack.referenceImages : [];
const referenceImage = referenceImages[0]?.comfyImage || referenceImages[0]?.fileName || referenceImages[0]?.objectPath || null;

try {
  const gateway = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://ai-gateway:8095/comfy/publication-submit',
    headers: {
      'Content-Type': 'application/json',
      'X-Request-Id': `publication-comfy-${job.publicationJobId}`
    },
    body: {
      job,
      promptPack,
      generationJobId: generation.generationJobId,
      referenceImage,
      dryRun: false
    },
    json: true,
    timeout: 120000
  });

  if (!gateway?.ok) {
    return [{
      json: {
        ok: false,
        submitted: false,
        error: gateway?.error || 'Comfy Cloud submission failed.',
        job,
        generation: {
          ...generation,
          status: 'error',
          runMode: 'comfy-cloud-api',
          provider: 'comfy-cloud',
          providerRequestId: gateway?.requestId || null,
          providerError: gateway || null
        }
      }
    }];
  }

  return [{
    json: {
      ok: true,
      submitted: true,
      job,
      generation: {
        ...generation,
        runMode: 'comfy-cloud-api',
        provider: 'comfy-cloud',
        providerRequestId: gateway.requestId || null,
        providerResponse: gateway.response || null,
        patched: gateway.patched || null
      }
    }
  }];
} catch (error) {
  return [{
    json: {
      ok: false,
      submitted: false,
      error: error?.message || 'Comfy Cloud gateway request failed.',
      job,
      generation: {
        ...generation,
        status: 'error',
        runMode: 'comfy-cloud-api',
        provider: 'comfy-cloud'
      }
    }
  }];
}
